$string['claudeconnect_check_wellknown_remedy'] = 'The webserver is not answering this URL at the domain root. Install the matching rewrite snippet from admin/tool/oauthmcp/.well-known-snippets/ into the virtual host (it cannot work from .htaccess) and reload the webserver. If it still returns 404 afterwards, a dotfile-blocking rule such as "RedirectMatch 404" may be swallowing /.well-known/ — see the note below the OAuth section.';
$string['claudeconnect_client_code_command'] = 'claude mcp add --transport http moodle-booking-wizard {$a->serverurl} --header "Authorization: Bearer YOUR_TOKEN"';
$string['claudeconnect_client_code_heading'] = 'Claude Code — exact command';
$string['claudeconnect_client_code_verify'] = 'No restart needed. Verify with <code>claude mcp list</code> or the <code>/mcp</code> panel — both show the connection status and the available tools. Add <code>--scope user</code> to make the server available in every project.';
$string['claudeconnect_client_desktop_config'] = '{
  "mcpServers": {
    "moodle-booking-wizard": {
      "command": "npx",
      "args": [
        "mcp-remote@latest",
        "{$a->serverurl}",
        "--header",
        "Authorization: Bearer YOUR_TOKEN"
      ]
    }
  }
}';
$string['claudeconnect_client_desktop_heading'] = 'Claude Desktop — exact configuration';
$string['claudeconnect_client_desktop_intro'] = 'Claude Desktop cannot call a remote MCP server directly from its config file — it starts a local bridge (<code>mcp-remote</code>) via <code>npx</code>. Merge the block below into <code>claude_desktop_config.json</code>; <code>mcpServers</code> belongs at the TOP level of the file, next to any existing keys.';
$string['claudeconnect_client_desktop_notes'] = 'The header must stay TWO separate array entries — <code>"--header"</code> and the full <code>"Authorization: Bearer …"</code> string; the combined <code>--header=…</code> form does not work. After saving, fully quit Claude Desktop (Cmd+Q) and reopen it. To keep the token out of the file, write <code>"Authorization: Bearer ${MY_TOKEN}"</code> and set <code>MY_TOKEN</code> in your environment instead.';
$string['claudeconnect_client_node_warning'] = 'Requires Node.js 20 or newer on your computer (check with <code>node -v</code>). With nvm and an older default version (e.g. 16) the bridge crashes with a cryptic "node:fs/promises does not provide an export named constants" error — fix it with <code>nvm alias default 22</code>, or pin <code>"command"</code> to the absolute path of a modern <code>npx</code> and add an <code>"env": {"PATH": "…"}</code> entry so the bridge and its Node version match.';
$string['claudeconnect_common_heading'] = 'Prerequisites (needed for both methods)';
$string['claudeconnect_howto'] = 'How to set it up:';
$string['claudeconnect_intro'] = 'Connect this Moodle site to Claude.';
$string['claudeconnect_intro_detail'] = 'Claude talks to this site through an MCP server (Model Context Protocol) provided by the tool_oauthmcp plugin. There is one endpoint, reachable in two different ways depending on your Claude client. This page checks the prerequisites for both and explains exactly how to set each one up.';
$string['claudeconnect_manual_fallback_hint'] = 'Prefer doing it by hand, or did the automatic setup report that it cannot run (or roll itself back)? The two manual recipes below cover both kinds of server access.';
$string['claudeconnect_menu'] = 'Connect with Claude';
$string['claudeconnect_method_oauth_detail'] = 'Best for the hosted Claude at claude.ai. You add the server URL as a custom connector and authenticate through your Moodle login; Claude stores the grant and refreshes it automatically. No token is ever copied into Claude.';
$string['claudeconnect_method_oauth_heading'] = 'Method 1 — OAuth 2.1 (browser login)';
$string['claudeconnect_method_oauth_summary'] = 'OAuth 2.1 (browser login) — for the hosted Claude at claude.ai (custom connectors). You add the server URL and sign in through your Moodle login in a browser window; there is no token to copy.';
$string['claudeconnect_method_token_detail'] = 'Best for Claude Code and Claude Desktop, which are configured from a file. You create a Moodle web-service token and give Claude the server URL plus that token as a Bearer credential. The token travels in the Authorization header, so the "Authorization header reaches PHP" prerequisite above must be green — on Apache with PHP-FPM that needs a one-line virtual-host addition.';
$string['claudeconnect_method_token_heading'] = 'Method 2 — Web-service token';
$string['claudeconnect_method_token_summary'] = 'Web-service token — for Claude Code and Claude Desktop. You add the same server URL together with a Moodle web-service token as a Bearer credential.';
$string['claudeconnect_methods_heading'] = 'Two ways to connect — pick the one that matches your Claude client:';
$string['claudeconnect_oauth_note'] = 'You never paste a password or token into Claude — the OAuth handshake keeps your credentials on your Moodle site, and you can revoke the access at any time.';
$string['claudeconnect_oauth_notready'] = 'Some OAuth prerequisites are not met yet (red crosses above). Fix them, then reload this page.';
$string['claudeconnect_oauth_notready_common'] = 'This method\'s own checks pass, but some of the common prerequisites at the top of this page are not met yet — fix the red crosses there, then reload this page.';
$string['claudeconnect_oauth_ready'] = 'All OAuth prerequisites are met — you can connect the hosted Claude now.';
$string['claudeconnect_oauth_step_add'] = 'Choose "Add custom connector".';
$string['claudeconnect_oauth_step_consent'] = 'Confirm on the consent screen that Claude may access the site on your behalf.';
$string['claudeconnect_oauth_step_done'] = 'Claude lists the available tools. You are connected.';
$string['claudeconnect_oauth_step_login'] = 'Claude opens your Moodle login in a browser window — sign in with your normal Moodle account.';
$string['claudeconnect_oauth_step_open'] = 'In Claude (claude.ai), open Settings → Connectors.';
$string['claudeconnect_oauth_step_paste'] = 'Paste this site\'s MCP server URL: <code>{$a->serverurl}</code>';
$string['claudeconnect_server_setup_ok'] = 'Server setup: the Authorization header and both discovery URLs all answer correctly — nothing to configure on the server.';
$string['claudeconnect_server_url_hint'] = 'This is the address you add to Claude. Both connection methods use it.';
$string['claudeconnect_server_url_label'] = 'MCP server URL (the same for both methods)';
$string['claudeconnect_skills_note'] = 'Good to know: the Booking Wizard\'s own skills are exposed to Claude automatically — you do not configure anything for them (they are delivered through a plugin hook, not through a web service). The dedicated "MCP server" web service is only for optionally publishing additional, generic Moodle web-service functions as tools; leaving it empty is fine.';
$string['claudeconnect_title'] = 'Connect with Claude';
$string['claudeconnect_token_note'] = 'Treat the token like a password: it grants access under your account. You can delete it at any time to revoke access.';
$string['claudeconnect_token_notready'] = 'Token authentication is not available yet (red cross above). Enable it, then reload this page.';
$string['claudeconnect_token_notready_common'] = 'This method\'s own checks pass, but some of the common prerequisites at the top of this page are not met yet — fix the red crosses there, then reload this page.';
$string['claudeconnect_token_ready'] = 'Token authentication is available — you can connect Claude Code or Claude Desktop with a token now.';
$string['claudeconnect_token_step_bearer'] = 'Add the HTTP header <code>Authorization: Bearer &lt;your token&gt;</code>, pasting the token you created in step 1.';
$string['claudeconnect_token_step_config'] = 'Open your MCP client configuration: in Claude Desktop, edit the <code>claude_desktop_config.json</code> file (Settings → Developer → Edit config); in Claude Code, run <code>claude mcp add</code>.';
$string['claudeconnect_token_step_create'] = 'Create a Moodle web-service token for your own account: open <a href="{$a->tokensurl}" target="_blank" rel="noopener">Site administration → Server → Web services → Manage tokens</a>, choose <em>Create token</em>, and select the <strong>MCP server (tool_oauthmcp)</strong> service. The token must be created for exactly this service — a token for any other service authenticates fine but exposes no tools.';
$string['claudeconnect_token_step_done'] = 'Restart Claude Code / Desktop — it lists the available tools. You are connected.';
$string['claudeconnect_token_step_url'] = 'Point the client at this site\'s MCP endpoint: <code>{$a->serverurl}</code>';
$string['claudeconnect_wellknown_heading'] = 'For server administrators: answering the /.well-known discovery URLs';
$string['claudeconnect_wellknown_htaccess_after'] = 'No reload is needed — .htaccess changes apply immediately. If the site errors after the change (HTTP 500), your host forbids one of the directives: restore the backup and use Option A, or ask your hosting support.';
$string['claudeconnect_wellknown_htaccess_intro'] = 'Append this block to the <code>.htaccess</code> file in the folder your domain points at — for a Moodle served directly under the domain that is the Moodle folder itself, where config.php lives. Create the file if it does not exist, and keep a backup copy of the previous version. The extra RewriteCond/RewriteRule pair passes the Authorization header through on FastCGI hosting, which strips it otherwise.';
$string['claudeconnect_wellknown_htaccess_title'] = 'Option B — no root access (managed hosting): use a .htaccess file';
$string['claudeconnect_wellknown_intro'] = 'The two OAuth discovery URLs must be answered at the DOMAIN ROOT, which a Moodle plugin cannot arrange by itself — this is the one step that happens on the server. Pick the option that matches your access; both blocks below are generated for this site, and both also pass the Authorization header through to PHP, which the token method needs too. Only this OAuth method needs the /.well-known rewrites themselves.';
$string['claudeconnect_wellknown_verify'] = 'Then verify from a terminal — this must print 200 — and reload this page:';
$string['claudeconnect_wellknown_vhost_after'] = 'Activate it: <code>a2enmod rewrite setenvif</code>, then <code>apache2ctl configtest</code> (must print "Syntax OK") and reload Apache. If the discovery rows above are still red afterwards, look for a hardened-vhost dotfile rule such as <code>RedirectMatch 404 /\..+</code> — it swallows /.well-known/ too. Replace it with <code>RedirectMatch 404 "/\.(?!well-known/)"</code> and check that paths like /.git/config still return 404.';
$string['claudeconnect_wellknown_vhost_intro'] = 'Find the site\'s SSL virtual-host file (<code>apache2ctl -S</code> prints it, usually under <code>/etc/apache2/sites-available/</code>), make a backup copy, then paste this inside the <code>&lt;VirtualHost *:443&gt;</code> block — not inside a Directory block. On nginx, use the equivalent from <code>admin/tool/oauthmcp/.well-known-snippets/nginx.conf.example</code> instead.';
$string['claudeconnect_wellknown_vhost_title'] = 'Option A — you have root access: add the rules to the virtual host (recommended)';
