$string['llm_debug_retention_days_desc'] = 'When AI debug mode is on, raw LLM exchanges are stored for diagnostics. Entries older than this number of days are deleted automatically by a scheduled task. Set to 0 to keep them indefinitely.';
$string['logreadskills'] = 'Log read-only skill executions';
$string['logreadskills_desc'] = 'Also record an audit event when a read-only skill runs (searches, diagnostics, look-ups). Read-only skills are the majority and the most frequent, so turning this off keeps the log focused on changes and denials without losing them. Writes and denials are always logged while skill execution logging is on.';
$string['logskillexecution'] = 'Log skill executions';
$string['logskillexecution_desc'] = 'Record an audit event every time the agent executes a skill or a skill is denied at a security gate, into the standard Moodle log store (Site administration > Reports > Logs). Recommended: keep on for an accountable audit trail of what the agent did, for whom, and when.';
$string['maxinputlength'] = 'Maximum input length';
